                if line.startswith('ii'):  # Only installed packages
                    parts = line.split()
                    if len(parts) >= 3:
                        package_name = parts[1]
                        version = parts[2]
                        package_list.append((package_name, version))

            # Get licenses for all packages concurrently
            packages = self._get_packages_with_licenses_concurrent(package_list)
            return packages

        except (subprocess.CalledProcessError, FileNotFoundError):
            return []

    def _get_packages_with_licenses_concurrent(self, package_list: List[Tuple[str, str]]) -> List[Dict[str, any]]:
        """Get package information with licenses using concurrent processing."""
        packages = []

        # Separate cached and uncached packages
        cached_packages = []
        uncached_packages = []

        for package_name, version in package_list:
            cached_licenses = self.cache.get("apt", package_name, version)
            if cached_licenses is not None:
                cached_packages.append({
                    "name": package_name,
                    "display_name": package_name,
                    "version": version,
                    "manager": "apt",
                    "licenses": cached_licenses
                })
            else:
                uncached_packages.append((package_name, version))

        packages.extend(cached_packages)

        # Process uncached packages concurrently
        if uncached_packages:
            max_workers = min(16, len(uncached_packages))  # Limit concurrent processes

            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                # Submit all license fetch tasks
