                    package_name, version = future_to_package[future]
                    try:
                        licenses = future.result()

                        # Cache the result
                        self.cache.set("apt", package_name, version, licenses)

                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "apt",
                            "licenses": licenses
                        })
                    except Exception as e:
                        # If license fetch fails, use unknown
                        packages.append({
                            "name": package_name,
                            "display_name": package_name,
                            "version": version,
                            "manager": "apt",
                            "licenses": ["unknown"]
                        })

        return packages

    def _get_apt_license_single(self, package_name: str, version: str) -> List[str]:
